from itertools import permutations
for p in permutations(range(7)):
    if p[1]!=1: continue
    vecs=set()
    ok=True
    for i in range(7):
        for j in range(i+1,7):
            v=(j-i,p[j]-p[i])
            if v in vecs: ok=False;break
            vecs.add(v)
        if not ok:break
    if ok:
        print(p);break
